/**
 * AsyncStorage keys for discovery features
 * MODULE-05-DISCOVERY-V3: Task DISCOVERY-V3-004
 * Source: SEARCH-FILTER-REQUIREMENTS.md § Appendix
 */
export const STORAGE_KEYS = {
  RECENT_SEARCHES: '@kids_marketplace:recent_searches',
  ACTIVE_FILTERS: '@kids_marketplace:active_filters', // session only
  BRAND_CACHE: '@kids_marketplace:brand_cache', // 5min TTL
} as const;

/**
 * File: p2p-kids-marketplace/src/utils/filterHelpers.ts
 * MODULE-05-DISCOVERY-V3: Filter Helper Utilities
 * Task: DISCOVERY-V3-004
 * 
 * Provides utility functions for filter management, validation, and display
 */

import { DiscoveryFilters, SortOption } from '../types/discovery';

/**
 * Count the number of active filters (excluding defaults)
 * 
 * @param filters - The current filter state
 * @returns Number of active filters
 * 
 * @example
 * countActiveFilters(getDefaultFilters()) // 0
 * countActiveFilters({ ...getDefaultFilters(), brand: 'Nike' }) // 1
 * countActiveFilters({ ...getDefaultFilters(), colors: ['red', 'blue'] }) // 1
 */
export function countActiveFilters(filters: DiscoveryFilters): number {
  let count = 0;

  // Query is an active filter if non-empty
  if (filters.query && filters.query.trim().length > 0) {
    count++;
  }

  // Category IDs count as 1 filter regardless of how many selected
  if (filters.categoryIds && filters.categoryIds.length > 0) {
    count++;
  }

  // Condition
  if (filters.condition) {
    count++;
  }

  // Price range (counts as 1 filter if either min or max is set)
  if (filters.minPrice !== undefined || filters.maxPrice !== undefined) {
    count++;
  }

  // Age group
  if (filters.ageGroup) {
    count++;
  }

  // Gender
  if (filters.gender) {
    count++;
  }

  // Brand
  if (filters.brand && filters.brand.trim().length > 0) {
    count++;
  }

  // Colors count as 1 filter regardless of how many selected
  if (filters.colors && filters.colors.length > 0) {
    count++;
  }

  // SP eligible only (counts only if true, since false is the default)
  if (filters.spEligibleOnly === true) {
    count++;
  }

  // Note: sortBy is NOT counted as an active filter (it's a sort option, not a filter)
  // Note: limit and offset are NOT counted (they're pagination params, not filters)

  return count;
}

/**
 * Format a filter key-value pair into a human-readable chip label
 * 
 * @param key - The filter key (camelCase)
 * @param value - The filter value
 * @returns Formatted label string
 * 
 * @example
 * formatFilterChipLabel('ageGroup', '3-5') // 'Age: 3-5'
 * formatFilterChipLabel('condition', 'like_new') // 'Condition: Like New'
 * formatFilterChipLabel('minPrice', 10) // 'Min: $10'
 * formatFilterChipLabel('brand', 'Nike') // 'Brand: Nike'
 * formatFilterChipLabel('spEligibleOnly', true) // 'SP Only'
 */
export function formatFilterChipLabel(key: string, value: any): string {
  switch (key) {
    case 'query':
      return `"${value}"`;

    case 'categoryIds':
      // For multiple categories, just show count
      if (Array.isArray(value)) {
        return value.length === 1 ? 'Category' : `${value.length} Categories`;
      }
      return 'Category';

    case 'condition':
      // Convert snake_case to Title Case
      const conditionFormatted = String(value)
        .split('_')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ');
      return `Condition: ${conditionFormatted}`;

    case 'minPrice':
      return `Min: $${value}`;

    case 'maxPrice':
      return `Max: $${value}`;

    case 'priceRange':
      // Special case when both min and max are provided as a range
      if (typeof value === 'object' && value.min !== undefined && value.max !== undefined) {
        return `$${value.min}-$${value.max}`;
      }
      return `Price: ${value}`;

    case 'ageGroup':
      return `Age: ${value}`;

    case 'gender':
      // Capitalize first letter
      return `Gender: ${String(value).charAt(0).toUpperCase() + String(value).slice(1)}`;

    case 'brand':
      return `Brand: ${value}`;

    case 'colors':
      // For multiple colors, just show count
      if (Array.isArray(value)) {
        return value.length === 1 ? String(value[0]).charAt(0).toUpperCase() + String(value[0]).slice(1) : `${value.length} Colors`;
      }
      return 'Color';

    case 'spEligibleOnly':
      return 'SP Only';

    default:
      // Fallback: convert camelCase to Title Case
      const formatted = key
        .replace(/([A-Z])/g, ' $1')
        .trim()
        .split(' ')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ');
      return `${formatted}: ${value}`;
  }
}

/**
 * Validate price range (min must not exceed max)
 * 
 * @param min - Minimum price (optional)
 * @param max - Maximum price (optional)
 * @returns true if valid, false if min > max
 * 
 * @example
 * validatePriceRange(10, 20) // true
 * validatePriceRange(20, 10) // false
 * validatePriceRange(undefined, 20) // true
 * validatePriceRange(10, undefined) // true
 * validatePriceRange(undefined, undefined) // true
 */
export function validatePriceRange(min?: number, max?: number): boolean {
  // If either is undefined, consider it valid
  if (min === undefined || max === undefined) {
    return true;
  }

  // Both defined: min must not exceed max
  return min <= max;
}

/**
 * Get the default filter state
 * 
 * @returns Default DiscoveryFilters object
 * 
 * @example
 * const defaults = getDefaultFilters();
 * // { sortBy: 'relevance', spEligibleOnly: false }
 */
export function getDefaultFilters(): DiscoveryFilters {
  return {
    sortBy: 'relevance' as SortOption,
    spEligibleOnly: false,
    // All other fields are undefined by default
  };
}

/**
 * Unit tests for filterHelpers utility
 * MODULE-05-DISCOVERY-V3: Task DISCOVERY-V3-004
 * 
 * Tests filter counting, chip label formatting, price validation, and defaults
 */

import {
  countActiveFilters,
  formatFilterChipLabel,
  validatePriceRange,
  getDefaultFilters,
} from '../../utils/filterHelpers';
import { DiscoveryFilters } from '../../types/discovery';

describe('filterHelpers utilities', () => {
  describe('countActiveFilters', () => {
    it('should return 0 for default filters', () => {
      const defaults = getDefaultFilters();
      expect(countActiveFilters(defaults)).toBe(0);
    });

    it('should count query as 1 filter', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        query: 'bicycle',
      };
      expect(countActiveFilters(filters)).toBe(1);
    });

    it('should not count empty query', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        query: '',
      };
      expect(countActiveFilters(filters)).toBe(0);
    });

    it('should not count whitespace-only query', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        query: '   ',
      };
      expect(countActiveFilters(filters)).toBe(0);
    });

    it('should count category IDs as 1 filter regardless of count', () => {
      const singleCategory: DiscoveryFilters = {
        ...getDefaultFilters(),
        categoryIds: ['cat1'],
      };
      expect(countActiveFilters(singleCategory)).toBe(1);

      const multipleCategories: DiscoveryFilters = {
        ...getDefaultFilters(),
        categoryIds: ['cat1', 'cat2', 'cat3'],
      };
      expect(countActiveFilters(multipleCategories)).toBe(1);
    });

    it('should not count empty category array', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        categoryIds: [],
      };
      expect(countActiveFilters(filters)).toBe(0);
    });

    it('should count condition as 1 filter', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        condition: 'like_new',
      };
      expect(countActiveFilters(filters)).toBe(1);
    });

    it('should count price range as 1 filter when min is set', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        minPrice: 10,
      };
      expect(countActiveFilters(filters)).toBe(1);
    });

    it('should count price range as 1 filter when max is set', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        maxPrice: 50,
      };
      expect(countActiveFilters(filters)).toBe(1);
    });

    it('should count price range as 1 filter when both min and max are set', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        minPrice: 10,
        maxPrice: 50,
      };
      expect(countActiveFilters(filters)).toBe(1);
    });

    it('should count age group as 1 filter', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        ageGroup: '3-5',
      };
      expect(countActiveFilters(filters)).toBe(1);
    });

    it('should count gender as 1 filter', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        gender: 'girl',
      };
      expect(countActiveFilters(filters)).toBe(1);
    });

    it('should count brand as 1 filter', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        brand: 'Nike',
      };
      expect(countActiveFilters(filters)).toBe(1);
    });

    it('should not count empty brand', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        brand: '',
      };
      expect(countActiveFilters(filters)).toBe(0);
    });

    it('should count colors as 1 filter regardless of count', () => {
      const singleColor: DiscoveryFilters = {
        ...getDefaultFilters(),
        colors: ['red'],
      };
      expect(countActiveFilters(singleColor)).toBe(1);

      const multipleColors: DiscoveryFilters = {
        ...getDefaultFilters(),
        colors: ['red', 'blue', 'green'],
      };
      expect(countActiveFilters(multipleColors)).toBe(1);
    });

    it('should not count empty colors array', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        colors: [],
      };
      expect(countActiveFilters(filters)).toBe(0);
    });

    it('should count SP eligible only when true', () => {
      const filtersTrue: DiscoveryFilters = {
        ...getDefaultFilters(),
        spEligibleOnly: true,
      };
      expect(countActiveFilters(filtersTrue)).toBe(1);

      const filtersFalse: DiscoveryFilters = {
        ...getDefaultFilters(),
        spEligibleOnly: false,
      };
      expect(countActiveFilters(filtersFalse)).toBe(0);
    });

    it('should not count sortBy as a filter', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        sortBy: 'price_asc',
      };
      expect(countActiveFilters(filters)).toBe(0);
    });

    it('should not count limit or offset as filters', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        limit: 20,
        offset: 40,
      };
      expect(countActiveFilters(filters)).toBe(0);
    });

    it('should correctly count multiple active filters', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        query: 'bicycle',
        categoryIds: ['cat1', 'cat2'],
        condition: 'good',
        minPrice: 10,
        maxPrice: 50,
        ageGroup: '6-8',
        gender: 'boy',
        brand: 'Schwinn',
        colors: ['red', 'blue'],
        spEligibleOnly: true,
      };
      expect(countActiveFilters(filters)).toBe(9); // All 9 filter dimensions
    });
  });

  describe('formatFilterChipLabel', () => {
    it('should format query', () => {
      expect(formatFilterChipLabel('query', 'bicycle')).toBe('"bicycle"');
    });

    it('should format single category', () => {
      expect(formatFilterChipLabel('categoryIds', ['cat1'])).toBe('Category');
    });

    it('should format multiple categories', () => {
      expect(formatFilterChipLabel('categoryIds', ['cat1', 'cat2', 'cat3'])).toBe('3 Categories');
    });

    it('should format condition with title case', () => {
      expect(formatFilterChipLabel('condition', 'like_new')).toBe('Condition: Like New');
      expect(formatFilterChipLabel('condition', 'new')).toBe('Condition: New');
      expect(formatFilterChipLabel('condition', 'good')).toBe('Condition: Good');
    });

    it('should format minPrice', () => {
      expect(formatFilterChipLabel('minPrice', 10)).toBe('Min: $10');
      expect(formatFilterChipLabel('minPrice', 25.5)).toBe('Min: $25.5');
    });

    it('should format maxPrice', () => {
      expect(formatFilterChipLabel('maxPrice', 50)).toBe('Max: $50');
      expect(formatFilterChipLabel('maxPrice', 100)).toBe('Max: $100');
    });

    it('should format age group', () => {
      expect(formatFilterChipLabel('ageGroup', '3-5')).toBe('Age: 3-5');
      expect(formatFilterChipLabel('ageGroup', '9-12')).toBe('Age: 9-12');
    });

    it('should format gender with capitalization', () => {
      expect(formatFilterChipLabel('gender', 'boy')).toBe('Gender: Boy');
      expect(formatFilterChipLabel('gender', 'girl')).toBe('Gender: Girl');
      expect(formatFilterChipLabel('gender', 'unisex')).toBe('Gender: Unisex');
    });

    it('should format brand', () => {
      expect(formatFilterChipLabel('brand', 'Nike')).toBe('Brand: Nike');
      expect(formatFilterChipLabel('brand', 'LEGO')).toBe('Brand: LEGO');
    });

    it('should format single color', () => {
      expect(formatFilterChipLabel('colors', ['red'])).toBe('Red');
      expect(formatFilterChipLabel('colors', ['blue'])).toBe('Blue');
    });

    it('should format multiple colors', () => {
      expect(formatFilterChipLabel('colors', ['red', 'blue'])).toBe('2 Colors');
      expect(formatFilterChipLabel('colors', ['red', 'blue', 'green'])).toBe('3 Colors');
    });

    it('should format SP eligible only', () => {
      expect(formatFilterChipLabel('spEligibleOnly', true)).toBe('SP Only');
    });

    it('should handle unknown keys with fallback formatting', () => {
      expect(formatFilterChipLabel('customKey', 'value')).toBe('Custom Key: value');
      expect(formatFilterChipLabel('anotherCustomKey', 123)).toBe('Another Custom Key: 123');
    });
  });

  describe('validatePriceRange', () => {
    it('should return true when min <= max', () => {
      expect(validatePriceRange(10, 20)).toBe(true);
      expect(validatePriceRange(10, 10)).toBe(true);
      expect(validatePriceRange(0, 100)).toBe(true);
    });

    it('should return false when min > max', () => {
      expect(validatePriceRange(20, 10)).toBe(false);
      expect(validatePriceRange(50, 25)).toBe(false);
      expect(validatePriceRange(100, 99)).toBe(false);
    });

    it('should return true when min is undefined', () => {
      expect(validatePriceRange(undefined, 20)).toBe(true);
      expect(validatePriceRange(undefined, 100)).toBe(true);
    });

    it('should return true when max is undefined', () => {
      expect(validatePriceRange(10, undefined)).toBe(true);
      expect(validatePriceRange(50, undefined)).toBe(true);
    });

    it('should return true when both are undefined', () => {
      expect(validatePriceRange(undefined, undefined)).toBe(true);
    });

    it('should handle edge cases with 0', () => {
      expect(validatePriceRange(0, 0)).toBe(true);
      expect(validatePriceRange(0, 10)).toBe(true);
      expect(validatePriceRange(10, 0)).toBe(false);
    });

    it('should handle negative numbers', () => {
      expect(validatePriceRange(-10, 10)).toBe(true);
      expect(validatePriceRange(-20, -10)).toBe(true);
      expect(validatePriceRange(10, -10)).toBe(false);
    });
  });

  describe('getDefaultFilters', () => {
    it('should return object with sortBy as relevance', () => {
      const defaults = getDefaultFilters();
      expect(defaults.sortBy).toBe('relevance');
    });

    it('should return object with spEligibleOnly as false', () => {
      const defaults = getDefaultFilters();
      expect(defaults.spEligibleOnly).toBe(false);
    });

    it('should have all other fields undefined', () => {
      const defaults = getDefaultFilters();
      expect(defaults.query).toBeUndefined();
      expect(defaults.categoryIds).toBeUndefined();
      expect(defaults.condition).toBeUndefined();
      expect(defaults.minPrice).toBeUndefined();
      expect(defaults.maxPrice).toBeUndefined();
      expect(defaults.ageGroup).toBeUndefined();
      expect(defaults.gender).toBeUndefined();
      expect(defaults.brand).toBeUndefined();
      expect(defaults.colors).toBeUndefined();
      expect(defaults.limit).toBeUndefined();
      expect(defaults.offset).toBeUndefined();
    });

    it('should return 0 active filters when countActiveFilters is called', () => {
      const defaults = getDefaultFilters();
      expect(countActiveFilters(defaults)).toBe(0);
    });
  });
});

/**
 * Integration tests for DISCOVERY-V3-004 utilities with discovery types
 * MODULE-05-DISCOVERY-V3: Task DISCOVERY-V3-004
 * 
 * Tests that utilities work correctly with real-world discovery filter scenarios
 */

import {
  countActiveFilters,
  formatFilterChipLabel,
  validatePriceRange,
  getDefaultFilters,
} from '../../utils/filterHelpers';
import { levenshteinDistance, findClosestMatch } from '../../utils/fuzzyMatch';
import { 
  DiscoveryFilters, 
  COLOR_PALETTE, 
  PRICE_PRESETS,
  STORAGE_KEYS,
} from '../../types/discovery';

describe('DISCOVERY-V3-004 Integration Tests', () => {
  describe('Filter utilities with real-world scenarios', () => {
    it('should correctly handle a typical user filter flow', () => {
      // User starts with defaults
      let filters = getDefaultFilters();
      expect(countActiveFilters(filters)).toBe(0);

      // User adds age filter
      filters = { ...filters, ageGroup: '3-5' };
      expect(countActiveFilters(filters)).toBe(1);
      expect(formatFilterChipLabel('ageGroup', filters.ageGroup)).toBe('Age: 3-5');

      // User adds gender filter
      filters = { ...filters, gender: 'girl' };
      expect(countActiveFilters(filters)).toBe(2);

      // User adds price range
      filters = { ...filters, minPrice: 10, maxPrice: 50 };
      expect(countActiveFilters(filters)).toBe(3);
      expect(validatePriceRange(filters.minPrice, filters.maxPrice)).toBe(true);

      // User adds colors
      filters = { ...filters, colors: ['pink', 'purple'] };
      expect(countActiveFilters(filters)).toBe(4);

      // User removes price range
      filters = { ...filters, minPrice: undefined, maxPrice: undefined };
      expect(countActiveFilters(filters)).toBe(3);
    });

    it('should handle edge case where user enters invalid price range', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        minPrice: 50,
        maxPrice: 20,
      };

      expect(validatePriceRange(filters.minPrice, filters.maxPrice)).toBe(false);
      // User should be prevented from applying this filter
    });

    it('should correctly format all filter types for chip display', () => {
      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        query: 'bike',
        categoryIds: ['cat1', 'cat2'],
        condition: 'like_new',
        minPrice: 10,
        maxPrice: 25,
        ageGroup: '6-8',
        gender: 'boy',
        brand: 'Schwinn',
        colors: ['red', 'blue', 'green'],
        spEligibleOnly: true,
      };

      // Verify we can format each filter for display
      expect(formatFilterChipLabel('query', filters.query)).toBe('"bike"');
      expect(formatFilterChipLabel('categoryIds', filters.categoryIds)).toBe('2 Categories');
      expect(formatFilterChipLabel('condition', filters.condition)).toBe('Condition: Like New');
      expect(formatFilterChipLabel('minPrice', filters.minPrice)).toBe('Min: $10');
      expect(formatFilterChipLabel('maxPrice', filters.maxPrice)).toBe('Max: $25');
      expect(formatFilterChipLabel('ageGroup', filters.ageGroup)).toBe('Age: 6-8');
      expect(formatFilterChipLabel('gender', filters.gender)).toBe('Gender: Boy');
      expect(formatFilterChipLabel('brand', filters.brand)).toBe('Brand: Schwinn');
      expect(formatFilterChipLabel('colors', filters.colors)).toBe('3 Colors');
      expect(formatFilterChipLabel('spEligibleOnly', filters.spEligibleOnly)).toBe('SP Only');

      expect(countActiveFilters(filters)).toBe(9);
    });

    it('should work with PRICE_PRESETS for quick filter selection', () => {
      // User selects "Under $10" preset
      const preset = PRICE_PRESETS[0];
      expect(preset.id).toBe('under-10');
      expect(preset.label).toBe('Under $10');

      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        minPrice: preset.min,
        maxPrice: preset.max,
      };

      expect(validatePriceRange(filters.minPrice, filters.maxPrice)).toBe(true);
      expect(countActiveFilters(filters)).toBe(1); // Price range counts as 1 filter
    });

    it('should work with COLOR_PALETTE for color selection', () => {
      // Verify COLOR_PALETTE structure
      expect(COLOR_PALETTE).toHaveLength(12);
      expect(COLOR_PALETTE[0]).toHaveProperty('id');
      expect(COLOR_PALETTE[0]).toHaveProperty('label');
      expect(COLOR_PALETTE[0]).toHaveProperty('hex');

      // User selects pink and purple colors
      const pinkColor = COLOR_PALETTE.find(c => c.id === 'pink');
      const purpleColor = COLOR_PALETTE.find(c => c.id === 'purple');

      expect(pinkColor).toBeDefined();
      expect(purpleColor).toBeDefined();

      const filters: DiscoveryFilters = {
        ...getDefaultFilters(),
        colors: [pinkColor!.id, purpleColor!.id],
      };

      expect(countActiveFilters(filters)).toBe(1); // Colors count as 1 filter
      expect(formatFilterChipLabel('colors', filters.colors)).toBe('2 Colors');
    });

    it('should validate STORAGE_KEYS are correctly defined', () => {
      expect(STORAGE_KEYS.RECENT_SEARCHES).toBe('@kids_marketplace:recent_searches');
      expect(STORAGE_KEYS.ACTIVE_FILTERS).toBe('@kids_marketplace:active_filters');
      expect(STORAGE_KEYS.BRAND_CACHE).toBe('@kids_marketplace:brand_cache');
    });
  });

  describe('Fuzzy match integration with COLOR_PALETTE', () => {
    it('should suggest correct color for typo', () => {
      const colorNames = COLOR_PALETTE.map(c => c.label);

      // User types "bule" instead of "blue"
      const suggestion = findClosestMatch('bule', colorNames, 3);
      expect(suggestion).toBe('Blue');

      // User types "pnk" instead of "pink"
      const suggestion2 = findClosestMatch('pnk', colorNames, 3);
      expect(suggestion2).toBe('Pink');
    });

    it('should handle case-insensitive color matching', () => {
      const colorNames = COLOR_PALETTE.map(c => c.label);

      const suggestion = findClosestMatch('RED', colorNames, 3);
      expect(suggestion).toBe('Red');

      const suggestion2 = findClosestMatch('YeLLoW', colorNames, 3);
      expect(suggestion2).toBe('Yellow');
    });

    it('should return null for colors too far from any match', () => {
      const colorNames = COLOR_PALETTE.map(c => c.label);

      const suggestion = findClosestMatch('xyz', colorNames, 2);
      expect(suggestion).toBeNull();
    });
  });

  describe('Complete filter workflow', () => {
    it('should handle full search and filter flow', () => {
      // Scenario: Parent searching for daughter's birthday gift
      let filters = getDefaultFilters();

      // 1. User types search query
      filters = { ...filters, query: 'doll' };
      expect(countActiveFilters(filters)).toBe(1);

      // 2. User selects age group
      filters = { ...filters, ageGroup: '3-5' };
